<?php if ( post_password_required() ) { return; } ?><section id="comments" class="comments-area site-container"><?php if ( have_comments() ) { ?><h2><?php printf( esc_html( _nx( 'One comment', '%1$s comments', get_comments_number(), 'comments title', 'rjy-group' ) ), esc_html( number_format_i18n( get_comments_number() ) ) ); ?></h2><ol class="comment-list"><?php wp_list_comments( array( 'style' => 'ol', 'short_ping' => true, 'avatar_size' => 48 ) ); ?></ol><?php the_comments_pagination(); } if ( ! comments_open() && get_comments_number() ) { ?><p><?php esc_html_e( 'Comments are closed.', 'rjy-group' ); ?></p><?php } comment_form(); ?></section>
